// shared logic
function parse(rows){const H=rows.length,W=rows[0].length;const L={W,H,walls:[],pits:[]};
for(let y=0;y<H;y++){L.walls.push([]);L.pits.push([]);for(let x=0;x<W;x++){const c=rows[y][x];
L.walls[y][x]=c==='#';L.pits[y][x]=c==='x';
if(c==='A')L.A=[x,y];if(c==='B')L.B=[x,y];if(c==='a')L.a=[x,y];if(c==='b')L.b=[x,y];}}return L;}
function mv(L,p,dx,dy){const nx=p[0]+dx,ny=p[1]+dy;
if(nx<0||ny<0||nx>=L.W||ny>=L.H||L.walls[ny][nx])return p;return [nx,ny];}
const D=[[1,0],[-1,0],[0,1],[0,-1]];
function solve(L){const key=s=>s.join(',');const s0=[...L.A,...L.B];const seen=new Map([[key(s0),null]]);let q=[s0];let depth=0;
while(q.length&&depth<60){const nq=[];for(const s of q){for(const [dx,dy] of D){
const a=mv(L,[s[0],s[1]],dx,dy),b=mv(L,[s[2],s[3]],-dx,dy);
if(L.pits[a[1]][a[0]]||L.pits[b[1]][b[0]])continue;const n=[...a,...b],k=key(n);if(seen.has(k))continue;seen.set(k,1);
if(a[0]==L.a[0]&&a[1]==L.a[1]&&b[0]==L.b[0]&&b[1]==L.b[1])return depth+1;nq.push(n);}}q=nq;depth++;}return -1;}
module.exports={parse,solve};
if(require.main===module){
let seed=12345;const r=()=>(seed=(seed*1664525+1013904223)>>>0)/4294967296;
const ri=n=>Math.floor(r()*n);
const targets=[2,5,8,11,14,17,20,24,28,32];const out=[];
for(const t of targets){let best=null;
for(let i=0;i<40000;i++){const W=7+ri(3),H=5+ri(2);
const g=[];for(let y=0;y<H;y++){g.push([]);for(let x=0;x<W;x++){const edge=x==0||y==0||x==W-1||y==H-1;
g[y][x]=edge?'#':(r()<0.22?'#':(r()<(t>10?0.07:0.0)?'x':'.'));}}
const free=[];for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++)if(g[y][x]==='.')free.push([x,y]);
if(free.length<8)continue;
for(const c of 'ABab'){const j=ri(free.length);const [x,y]=free.splice(j,1)[0];g[y][x]=c;}
const rows=g.map(a=>a.join(''));const d=solve(parse(rows));
if(d>=t&&d<=t+3){best={rows,d};break;}
if(d>0&&(!best||Math.abs(d-t)<Math.abs(best.d-t)))best={rows,d};}
out.push(best);}
console.log(JSON.stringify(out.map(o=>o.rows)));console.error(out.map(o=>o.d).join(' '));}
EOF
cd /tmp/gen && node gen.js > levels.json; cat levels.json | head -c 600

