let scr='title';

// ---- audio
let ac;function tone(f,d=.09,t='sine',v=.07,when=0,slide=0){try{ac=ac||new (window.AudioContext||window.webkitAudioContext)();
const o=ac.createOscillator(),g=ac.createGain(),t0=ac.currentTime+when;o.type=t;o.frequency.setValueAtTime(f,t0);if(slide)o.frequency.exponentialRampToValueAtTime(f*slide,t0+d);
g.gain.setValueAtTime(v,t0);g.gain.exponentialRampToValueAtTime(.0001,t0+d);o.connect(g).connect(ac.destination);o.start(t0);o.stop(t0+d+.02);}catch(e){}}
const sfx={move(){tone(300,.07,'triangle',.06);tone(420,.07,'triangle',.04,.0)},flip(){tone(520,.18,'square',.04,0,1.8)},
 fell(){tone(220,.3,'sawtooth',.05,0,.4)},bump(){tone(110,.08,'square',.04)},win(){[523,659,784,1047].forEach((f,i)=>tone(f,.25,'triangle',.07,i*.09))},undo(){tone(360,.08,'sine',.05,0,.7)}};

// ---- game state
let li=0,L,S,hist,moves,won,padFlash,disp,particles=[],shake=0,fellFlash=0,lastDir=0,ruleBump=0;
const c=$('c'),ctx=c.getContext('2d');let T=40,ox=0,oy=0,DPR=1;
function loadLevel(i){li=i;save.cur=i;persist();L=parse(LEVELS[i].rows);S=startState(L);hist=[];moves=0;won=false;
padFlash=L.pads.map(r=>r.map(()=>0));disp=[S[0],S[1],S[2],S[3]];particles=[];$('win').classList.remove('on');
$('hint').textContent=HINTS[i]||'';$('lname').textContent='LEVEL '+(i+1);updateHud();show('game');fit();loop();}
function updateHud(){$('mc').textContent=moves+' moves · par '+LEVELS[li].par;
const h=$('ph'),v=$('pv');h.querySelector('span').textContent=S[4]<0?'mirrored':'same';v.querySelector('span').textContent=S[5]>0?'same':'flipped';}
function fit(){const st=$('stage');if(!st||!L)return;const w=st.clientWidth-4,h=st.clientHeight-4;DPR=window.devicePixelRatio||1;
T=Math.max(16,Math.floor(Math.min(w/L.W,h/L.H,84)));c.style.width=T*L.W+'px';c.style.height=T*L.H+'px';c.width=T*L.W*DPR;c.height=T*L.H*DPR;}
function move(d){if(scr!=='game'||won)return;const r=step(L,S,d);
if(r.fell){fellFlash=1;shake=8;sfx.fell();return;}
if(!r.moved){shake=3;sfx.bump();return;}
hist.push(S);const old=S;S=r.s;moves++;lastDir=d;
let flipped=false;[[0,1],[2,3]].forEach(([a,b])=>{if(S[a]!==old[a]||S[b]!==old[b]){const p=L.pads[S[b]][S[a]];if(p){padFlash[S[b]][S[a]]=1;flipped=true;}}});
if(flipped){sfx.flip();[$('ph'),$('pv')].forEach((p,k)=>{const ch=(k===0?S[4]!==old[4]:S[5]!==old[5]);if(ch){p.classList.add('flip');setTimeout(()=>p.classList.remove('flip'),450);}});}else sfx.move();
updateHud();
if(isWin(L,S)){won=true;const st=starsFor(li,moves);
if(save.best[li]===undefined||moves<save.best[li]){save.best[li]=moves;}persist();
setTimeout(()=>{sfx.win();burst();$('stars').innerHTML=[1,2,3].map(n=>'<i class="'+(n<=st?'on':'')+'">★</i>').join('');
$('wmsg').textContent=moves+' moves'+(moves<=LEVELS[li].par?' — perfect!':' · par '+LEVELS[li].par);
$('wnext').style.display=li<LEVELS.length-1?'':'none';
if(li===LEVELS.length-1)$('wmsg').textContent+='\nYou finished Mirror Twins!';$('win').classList.add('on');},380);}}
function undo(){if(!hist.length||won)return;S=hist.pop();moves--;updateHud();sfx.undo();}
function burst(){for(const k of [[S[0],S[1],'#5eead4'],[S[2],S[3],'#fbbf24']])for(let i=0;i<26;i++){const a=Math.random()*6.28,v=1+Math.random()*3.2;
particles.push({x:(k[0]+.5)*T,y:(k[1]+.5)*T,vx:Math.cos(a)*v,vy:Math.sin(a)*v-1,l:1,c:k[2]});}}

// ---- drawing
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
let raf=0,tm=0;function loop(){if(!raf)raf=requestAnimationFrame(frame);}
function frame(t){raf=0;tm=t/1000;if(scr==='game'&&L){draw();raf=requestAnimationFrame(frame);}}
function draw(){const W=L.W*T,H=L.H*T;ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);
let sx=0,sy=0;if(shake>.2){sx=(Math.random()-.5)*shake;sy=(Math.random()-.5)*shake;shake*=.8;}ctx.translate(sx,sy);
for(let i=0;i<4;i++)disp[i]+=(S[i]-disp[i])*.38;
for(let y=0;y<L.H;y++)for(let x=0;x<L.W;x++){const px=x*T,py=y*T;
if(L.walls[y][x]){ctx.fillStyle='#232853';rr(px+2,py+3,T-4,T-4,T*.2);ctx.fill();ctx.fillStyle='#4a5190';rr(px+2,py+1,T-4,T-5,T*.2);ctx.fill();ctx.fillStyle='#5b63a8';rr(px+5,py+4,T-10,T*.18,T*.1);ctx.fill();continue;}
ctx.fillStyle=(x+y)%2?'#1b1f4a':'#181c43';ctx.fillRect(px,py,T,T);
if(L.pits[y][x]){const g=ctx.createRadialGradient(px+T/2,py+T/2,2,px+T/2,py+T/2,T*.4);g.addColorStop(0,'#000');g.addColorStop(1,'#0a0b1d');ctx.fillStyle=g;ctx.beginPath();ctx.arc(px+T/2,py+T/2,T*.38,0,7);ctx.fill();ctx.strokeStyle='#ef4444aa';ctx.lineWidth=2;ctx.stroke();}
const p=L.pads[y][x];if(p){const col=p==='f'?'#c084fc':'#4ade80',pulse=.5+.5*Math.sin(tm*3+x+y),fl=padFlash[y][x];padFlash[y][x]*=.9;
ctx.save();ctx.translate(px+T/2,py+T/2);ctx.shadowColor=col;ctx.shadowBlur=T*(.15+.2*pulse+fl);ctx.fillStyle=col+'33';ctx.strokeStyle=col;ctx.lineWidth=2.5;
ctx.beginPath();for(let k=0;k<6;k++){const a=k*Math.PI/3+Math.PI/6;ctx.lineTo(Math.cos(a)*T*.38,Math.sin(a)*T*.38);}ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;
ctx.fillStyle=col;ctx.font='bold '+Math.floor(T*.42)+'px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(p==='f'?'⇄':'⇅',0,1);ctx.restore();}}
const ring=(g,col,on)=>{const x=(g[0]+.5)*T,y=(g[1]+.5)*T,pu=.5+.5*Math.sin(tm*3);ctx.save();ctx.strokeStyle=col;ctx.lineWidth=T*.07;ctx.shadowColor=col;ctx.shadowBlur=on?T*.5:T*.12*pulseK(pu);
if(!on)ctx.setLineDash([T*.12,T*.1]);ctx.beginPath();ctx.arc(x,y,T*.36+pu*1.5,0,7);ctx.stroke();ctx.restore();};
const pulseK=p=>.5+p;
const onA=S[0]===L.a[0]&&S[1]===L.a[1],onB=S[2]===L.b[0]&&S[3]===L.b[1];
ring(L.a,'#5eead4',onA);ring(L.b,'#fbbf24',onB);
const tok=(x,y,col,dark,mx)=>{const cx=(x+.5)*T,cy=(y+.5)*T+Math.sin(tm*2+mx)*T*.015,r=T*.29;ctx.save();ctx.shadowColor=col;ctx.shadowBlur=T*.3;
const g=ctx.createRadialGradient(cx-r*.35,cy-r*.4,r*.1,cx,cy,r*1.1);g.addColorStop(0,'#fff');g.addColorStop(.25,col);g.addColorStop(1,dark);ctx.fillStyle=g;ctx.beginPath();ctx.arc(cx,cy,r,0,7);ctx.fill();ctx.restore();
const e=DIRS[lastDir];ctx.fillStyle='#071';ctx.fillStyle='#0b1030';for(const s of [-1,1]){ctx.beginPath();ctx.arc(cx+s*r*.36+e[0]*r*.12,cy-r*.1+e[1]*r*.12,r*.14,0,7);ctx.fill();}};
tok(disp[0],disp[1],'#5eead4','#0f766e',0);tok(disp[2],disp[3],'#fbbf24','#b45309',2);
for(const p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.08;p.l-=.02;}particles=particles.filter(p=>p.l>0);
for(const p of particles){ctx.globalAlpha=p.l;ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,T*.07*p.l+1,0,7);ctx.fill();}ctx.globalAlpha=1;
if(fellFlash>.01){ctx.fillStyle='rgba(239,68,68,'+fellFlash*.35+')';ctx.fillRect(-9,-9,W+18,H+18);fellFlash*=.9;}}

// ---- map / title
function buildMap(){const root=$('chaps');root.innerHTML='';
CHAPTERS.forEach((ch,ci)=>{const d=document.createElement('div');d.className='chap';d.innerHTML='<h3>'+(ci+1)+' · '+ch.name+'</h3><div class="blurb">'+ch.blurb+'</div><div class="grid"></div>';
const gr=d.querySelector('.grid');for(let i=ch.from;i<=ch.to;i++){const b=document.createElement('button');b.className='lv'+(i===save.cur?' cur':'');b.disabled=!unlocked(i);
const bs=save.best[i];b.innerHTML='<b>'+(i+1)+'</b><small>'+(bs===undefined?'· · ·':'★'.repeat(starsFor(i,bs))+'<span style="opacity:.25">'+'★'.repeat(3-starsFor(i,bs))+'</span>')+'</small>';
b.onclick=()=>loadLevel(i);gr.appendChild(b);}root.appendChild(d);});}
